data.query:
query Query($where: QualitySpecificationGroupWhereInput, $orderBy: [QualitySpecificationGroupOrderByInput!], $first: Int, $after: String) {
  qualitySpecificationGroup(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
        usable
        specifications {
          edges {
            node {
              required
              specification {
                id
                name
                expectedValue
                lowerBound
                upperBound
                type {
                  attribute
                  quality
                  quantity
                }
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
(

  $specs := $state.context.LOCAL.group.specifications.edges.node;
  $checks := $state.context.REQUEST.qualityChecks;
  $previousChecks := state.context.LOCAL.qualityReport.qualityChecks.edges.node;
  $reportId:= $state.context.LOCAL.qualityReport.id;
  $checkFunction := function($a, $c){
    (
      $check := $not($isNilOrEmpty($previousChecks[specificationId=$c.specifcation.id])) ? $previousChecks[specificationId=$c.specifcation.id] :$checks[qualitySpecificationId=$c.specification.id];
        $isNilOrEmpty($check.qualitySpecificationId) or $isNilOrEmpty($check.value) ? $append($a,{
            "qualitySpecificationId": $c.specification.id,
            "value": null,
            "result":false,
            "note": "",
            "missing":$c.required ? true : false,
            "reportId": $reportId,
            "id": $check.qualitySpecificationId
          }) : 
            $c.specification.type.attribute ?
              $append($a,{
                "qualitySpecificationId": $check.qualitySpecificationId,
                "value": $check.value,
                "note": $check.note,
                "result": $check.value ? $uppercase($c.specification.expectedValue) = "TRUE" : $uppercase($c.specification.expectedValue) = "FALSE" or $isNilOrEmpty($c.specification.expectedValue),
                "reportId": $reportId,
                 "id": $check.id
              }) :
            $c.specification.type.quantity ?
              $append($a, {
                "qualitySpecificationId": $check.qualitySpecificationId,
                "value": $check.value,
                "note": $check.note,
                "result": $isNilOrEmpty($c.specification.expectedValue) ? 
                  $parseNumber($check.value) < $parseNumber($c.specification.upperBound) and  $parseNumber($check.value) > $parseNumber($c.specification.lowerBound) :
                  $parseNumber($check.value) = $parseNumber($c.specification.upperBound) or ($parseNumber($check.value) < $parseNumber($c.specification.upperBound) and  $parseNumber($check.value) > $parseNumber($c.specification.lowerBound)),
                  "reportId": $reportId,
                   "id": $check.qualitySpecificationId
              }) :
              $c.specification.type.quality ? 
                 $append($a, {
                "qualitySpecificationId": $check.qualitySpecificationId,
                "value": $check.value,
                "note": $check.note,
                "result": $uppercase($trim($check.value)) = $uppercase($trim($c.specification.expectedValue)),
                "reportId": $reportId,
                 "id": $check.qualitySpecificationId
              });
    )
  };
  $validatedChecks := $reduce($specs, $checkFunction,[])

)

