query Query($where: QualityReportWhereInput, $orderBy: [QualityReportOrderByInput!], $first: Int, $after: String) {
  qualityReport(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        qualityChecks{
          edges {
            node {
              id
              note
              value
              qualitySpecificationId
            }
          }
        }
      }
    }
  }
}

